const lockDocTree = `-- name: LockDocTree :exec

SELECT pg_advisory_xact_lock(hashtextextended($1::uuid::text || ':doc_tree', 0))
`

// Knowledge base (MUL-8370). See migration 610 for the model.
// Serializes folder/doc moves within one workspace so the cycle check and the
// move it guards see the same tree.
func (q *Queries) LockDocTree(ctx context.Context, workspaceID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, lockDocTree, workspaceID)
	return err
}

const markDocRead = `-- name: MarkDocRead :one
INSERT INTO doc_read (doc_id, user_id, workspace_id, seen_at)
VALUES ($1, $2, $3, now())
ON CONFLICT (doc_id, user_id) DO UPDATE SET seen_at = now()
RETURNING doc_id, user_id, workspace_id, seen_at
`

type MarkDocReadParams struct {
	DocID       pgtype.UUID `json:"doc_id"`
	UserID      pgtype.UUID `json:"user_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

func (q *Queries) MarkDocRead(ctx context.Context, arg MarkDocReadParams) (DocRead, error) {
	row := q.db.QueryRow(ctx, markDocRead, arg.DocID, arg.UserID, arg.WorkspaceID)
	var i DocRead
	err := row.Scan(
		&i.DocID,
		&i.UserID,
		&i.WorkspaceID,
		&i.SeenAt,
	)
	return i, err
}

const moveDoc = `-- name: MoveDoc :one
UPDATE doc SET folder_id = $1
WHERE id = $2 AND workspace_id = $3
RETURNING id, workspace_id, folder_id, format, title, content, revision, version_count, created_by_type, created_by_id, updated_by_type, updated_by_id, created_at, updated_at
`

type MoveDocParams struct {
	FolderID    pgtype.UUID `json:"folder_id"`
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

// A move is not an edit: revision and updated_at stay put so an open editor
// does not see a conflict and the doc does not jump in "recently edited".
func (q *Queries) MoveDoc(ctx context.Context, arg MoveDocParams) (Doc, error) {
	row := q.db.QueryRow(ctx, moveDoc, arg.FolderID, arg.ID, arg.WorkspaceID)
	var i Doc
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.FolderID,
		&i.Format,
		&i.Title,
		&i.Content,
		&i.Revision,
		&i.VersionCount,
		&i.CreatedByType,
		&i.CreatedByID,
		&i.UpdatedByType,
		&i.UpdatedByID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

